      "key": "obs_1",
      "facet": "term",
      "statement": "A priority queue is a common use for a heap.",
      "start_line": 1,
      "end_line": 1
    },
    {
      "key": "obs_2",
      "facet": "mechanism",
      "statement": "Tuple comparison breaks for (priority, task) pairs if the priorities are equal and the tasks do not have a default comparison order.",
      "start_line": 5,
      "end_line": 5
    },
    {
      "key": "obs_3",
      "facet": "mechanism",
      "statement": "A solution to challenges involving equal priorities and task comparison is to store priority, an entry count, and the task.",
      "start_line": 9,
      "end_line": 9
    },
    {
      "key": "obs_4",
      "facet": "property",
      "statement": "The entry count serves as a tie-breaker and prevents tuple comparison from directly comparing tasks.",
      "start_line": 9,
      "end_line": 9
    }
  ],
  "claims": [
    {
      "key": "claim_1",
      "status": "DERIVED_INTERPRETATION",
      "supported_by": [
        "obs_3",
        "obs_4"
      ],
      "statement": "Storing an entry count alongside priority and task allows the heap to maintain insertion order for equal priorities without requiring the task objects to be comparable."
    }
  ],
  "questions": [
    {
      "question": "How do you move a task to a new position in the heap if its priority changes?",
      "reason": "The source identifies this as a challenge but does not provide the mechanism for updating positions, which is critical for implementing mutable priority queues.",
      "evidence_needed": "Mechanism for updating heap positions upon priority change.",
      "derived_from": []
    },
    {
      "question": "How do you find and remove a pending task from the queue?",
      "reason": "The source identifies deletion as a challenge but does not provide the mechanism for locating and removing arbitrary elements, which is a key operational requirement.",
      "evidence_needed": "Mechanism for locating and removing arbitrary tasks from the heap.",
